old:
    if let Some(payload) = output.response.dnd_release_payload::<DragPayload>() {
        if payload.kind == AssetKind::Mesh {
            self.create_entity_from_dropped_asset(&payload, None);
        } else if payload.kind == AssetKind::Material {
            self.assign_dropped_material(ui, payload.asset_id.clone());
        }
    }
}

new:
    if let Some(payload) = output.response.dnd_release_payload::<DragPayload>() {
        if payload.kind == AssetKind::Mesh {
            self.create_entity_from_dropped_asset(&payload, None);
        } else if payload.kind == AssetKind::Material {
            self.assign_dropped_material(ui, payload.asset_id.clone());
        }
    }
    if let Some(payload) = output
        .response
        .dnd_release_payload::<crate::native_2d_editor::SpriteRegionDragPayload>()
    {
        let sorting_layer = self
            .project_root
            .as_ref()
            .and_then(|project| engine_authoring::ProjectSettings::load(project.path()).ok())
            .and_then(|settings| settings.native_2d.sorting_layers.first().cloned())
            .map(|layer| layer.id);
        let Some(sorting_layer) = sorting_layer else {
            self.session
                .push_diagnostic(engine_authoring::Diagnostic::error(
                    "editor.native_2d.missing_sorting_layer",
                    "Native 2D sprite placement requires at least one Project Settings sorting layer",
                ));
            return;
        };
        let placement = ui
            .ctx()
            .pointer_interact_pos()
            .and_then(|position| self.scene_view.placement_point_last_frame(position))
            .unwrap_or([0.0, 0.0, 0.0]);
        match self.session.create_entity_from_sprite_ref(
            payload.sprite.clone(),
            sorting_layer,
            None,
        ) {
            Ok(entity) => {
                let _ = self
                    .session
                    .set_scene_entity_positions([entity.clone()], placement.map(Some));
                self.select_single_entity(Some(entity));
                self.refresh_scene_problems();
            }
            Err(error) => self.apply_ui_result::<(), _>(Err(error)),
        }
    }
}
